// ---- Generic functions ----

// ---- Generic function to find the maximum ----
fn max_value<T: PartialOrd>(a: T, b: T) -> T {
    if a > b {
        a
    } else {
        b
    }
}

// ---- Generic function to swap values ----
fn swap_values<T>(a: T, b: T) -> (T, T) {
    (b, a)
}

// ---- Generic function to create a Vec from a value ----
fn to_vec<T: Clone>(value: T, count: usize) -> Vec<T> {
    let mut vec = Vec::new();
    for _ in 0..count {
        vec.push(value.clone());
    }
    vec
}

// ---- Generic structs ----
struct Point<T> {
    x: T,
    y: T,
}

impl<T> Point<T> {
    fn new(x: T, y: T) -> Self {
        Point { x, y }
    }

    fn x(&self) -> &T {
        &self.x
    }

    fn y(&self) -> &T {
        &self.y
    }
}

// ---- Generic struct with different types ----
struct Pair<T, U> {
    first: T,
    second: U,
}

impl<T, U> Pair<T, U> {
    fn new(first: T, second: U) -> Self {
        Pair { first, second }
    }

    fn first(&self) -> &T {
        &self.first
    }

    fn second(&self) -> &U {
        &self.second
    }
}

// ---- Generic methods with different types ----
impl<T> Point<T> {
    fn into_tuple(self) -> (T, T) {
        (self.x, self.y)
    }
}

// ---- Generic enum ----
enum Result<T, E> {
    Ok(T),
    Err(E),
}

// ---- Using generics ----
fn main() {
    // ---- Generic functions ----
    let max_int = max_value(10, 20);
    let max_float = max_value(3.14, 2.71);
    let max_char = max_value('a', 'z');

    println!("max_int: {}", max_int);
    println!("max_float: {}", max_float);
    println!("max_char: {}", max_char);

    let swapped = swap_values(1, 2);
    println!("Swapped: {:?}", swapped);

    let vec = to_vec(42, 3);
    println!("Vec: {:?}", vec);

    // ---- Generic structs ----
    let point1 = Point::new(10, 20);
    let point2 = Point::new(3.14, 2.71);
    let point3 = Point::new("x", "y");

    println!("point1: ({}, {})", point1.x, point1.y);
    println!("point2: ({}, {})", point2.x, point2.y);
    println!("point3: ({}, {})", point3.x, point3.y);

    // ---- Generic struct with different types ----
    let pair = Pair::new(42, "hello");
    println!("Pair: ({}, {})", pair.first(), pair.second());

    // ---- Generic methods ----
    let tuple = point1.into_tuple();
    println!("Tuple: {:?}", tuple);

    // ---- Generic enum ----
    let result: Result<i32, &str> = Result::Ok(42);
    let error: Result<i32, &str> = Result::Err("error");

    match result {
        Result::Ok(value) => println!("Success: {}", value),
        Result::Err(e) => println!("Error: {}", e),
    }
}

// ---- Generic with multiple bounds ----
fn print_point<T: std::fmt::Display>(point: &Point<T>) {
    println!("({}, {})", point.x, point.y);
}

// ---- Generic with where clause ----
fn compare_points<T>(p1: &Point<T>, p2: &Point<T>) -> bool
where
    T: PartialEq,
{
    p1.x == p2.x && p1.y == p2.y
}

